    teaserTitle1:     { en: 'Same estate.',          it: 'Stessa tenuta.',         es: 'Misma finca.',            fr: 'Même domaine.',          pt: 'Mesma herdade.',          cs: 'Stejný statek.'          },
    teaserTitle2:     { en: 'A different',           it: 'Una diversa',            es: 'Una diferente',           fr: 'Une autre',              pt: 'Uma diferente',           cs: 'Jiný'                    },
